targets.expr:
sum by (project, hostname, gpu_index, gpu_name, gpu_uuid, pci_bus_id) (
  increase(gpu_active_seconds_total{project=~"$project",hostname=~"$hostname",gpu_index=~"$gpu"}[$__range])
) / 3600

sum by (project, hostname, gpu_index, gpu_name, gpu_uuid, pci_bus_id) (
  increase(gpu_utilization_weighted_seconds_total{project=~"$project",hostname=~"$hostname",gpu_index=~"$gpu"}[$__range])
) / 3600

max by (project, hostname, gpu_index, gpu_name, gpu_uuid, pci_bus_id) (
  max_over_time(gpu_utilization_percent{project=~"$project",hostname=~"$hostname",gpu_index=~"$gpu"}[$__range])
)

max by (project, hostname, gpu_index, gpu_name, gpu_uuid, pci_bus_id) (
  quantile_over_time(0.95, gpu_utilization_percent{project=~"$project",hostname=~"$hostname",gpu_index=~"$gpu"}[$__range])
)

sum by (project, hostname, gpu_index, gpu_name, gpu_uuid, pci_bus_id) (
  increase(gpu_activity_windows_total{project=~"$project",hostname=~"$hostname",gpu_index=~"$gpu"}[$__range])
)
